const SHARE_IT=document.documentElement.lang==='it';
document.querySelectorAll('.fn-share').forEach(button=>{button.addEventListener('click',async()=>{const url=location.origin+location.pathname;const data={title:document.title,url};if(navigator.share){try{await navigator.share(data);return}catch(error){if(error.name==='AbortError')return}}try{await navigator.clipboard.writeText(url);button.textContent=(SHARE_IT?'Link copiato ✓':'Link copied ✓');setTimeout(()=>button.textContent=(SHARE_IT?'Condividi l’itinerario ↗':'Share itinerary ↗'),2500)}catch{const field=document.createElement('input');field.value=url;field.readOnly=true;field.setAttribute('aria-label',(SHARE_IT?'Link dell’itinerario da copiare':'Itinerary link to copy'));button.after(field);field.focus();field.select();button.textContent=(SHARE_IT?'Copia il link qui sotto':'Copy the link below')}})});